import{_ as p,a0 as l,w as o,s as r,ao as d,I as n,x as s,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"科学音频处理（一）：怎样使用 Octave 对音频文件进行读写操作 | LCTT x X-CMD","titleTemplate":false,"description":"科学音频处理（一）：怎样使用 Octave 对音频文件进行读写操作 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"科学音频处理（一）：怎样使用 Octave 对音频文件进行读写操作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"科学音频处理（一）：怎样使用 Octave 对音频文件进行读写操作 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160616 Part 1 - Scientific Audio Processing How to read and write Audio files with Octave 4.0.0 on Ubuntu","title":"科学音频处理（一）：怎样使用 Octave 对音频文件进行读写操作","tag":"201609","desc":""},"relativePath":"201609/20160616 Part 1 - Scientific Audio Processing How to read and write Audio files with Octave 4.0.0 on Ubuntu.md","filePath":"[post].md"}'),g={name:"201609/20160616 Part 1 - Scientific Audio Processing How to read and write Audio files with Octave 4.0.0 on Ubuntu.md"};function h(c,a,u,f,b,k){const e=l("Link");return o(),r("div",null,[a[13]||(a[13]=d(`<h1 id="科学音频处理-一-怎样使用-octave-对音频文件进行读写操作" tabindex="-1">科学音频处理（一）：怎样使用 Octave 对音频文件进行读写操作 <a class="header-anchor" href="#科学音频处理-一-怎样使用-octave-对音频文件进行读写操作" aria-label="Permalink to “科学音频处理（一）：怎样使用 Octave 对音频文件进行读写操作”">​</a></h1><p>Octave 是一个类似于 Linux 上的 Matlab 的软件，它拥有数量众多的函数和命令，支持声音采集、记录、回放以及音频信号的数字化处理，用于娱乐应用、研究、医学以及其它科学领域。在本教程中，我们会在 Ubuntu 上使用 Octave 的 4.0.0 版本读取音频文件，然后通过生成信号并且播放来模仿在各种情况下对音频信号的使用。</p><p>本教程中关注的不是安装和学习使用安装好的音频处理软件，而是从设计和音频工程的角度理解它是如何工作的。</p><h3 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to “环境准备”">​</a></h3><p>首先是安装 octave，在 Ubuntu 终端运行下面的命令添加 Octave PPA，然后安装 Octave 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:octave/stable</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install octave</span></span></code></pre></div><h3 id="步骤1-打开-octave" tabindex="-1">步骤1：打开 Octave <a class="header-anchor" href="#步骤1-打开-octave" aria-label="Permalink to “步骤1：打开 Octave”">​</a></h3><p>在这一步中我们单击软件图标打开 Octave，可以通过单击下拉式按钮选择工作路径。</p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/initial.png" alt=""></p><h3 id="步骤2-音频信息" tabindex="-1">步骤2：音频信息 <a class="header-anchor" href="#步骤2-音频信息" aria-label="Permalink to “步骤2：音频信息”">​</a></h3><p>使用<code>audioinfo</code>命令查看要处理的音频文件的相关信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; info = audioinfo (&#39;testing.ogg&#39;)</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/audioinfo.png" alt=""></p><h3 id="步骤3-读取音频文件" tabindex="-1">步骤3：读取音频文件 <a class="header-anchor" href="#步骤3-读取音频文件" aria-label="Permalink to “步骤3：读取音频文件”">​</a></h3><p>在本教程中我会使用 ogg 文件来读取这种文件的属性，比如采样、音频类型（stereo 和 mono）、信道数量等。必须声明的一点是教程中使用的所有的命令都是在 Octave 终端窗口中执行的。首先，我们必须要把这个 ogg 文件赋给一个变量。注意：<strong>文件必须在 Octave 的工作路径中。</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; file=&#39;yourfile.ogg&#39;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [M, fs] = audioread(file)</span></span></code></pre></div><p>这里的 M 是一个一列或两列的矩阵，取决于信道的数量，fs 是采样率。</p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/reading.png" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/matrix.png" alt=""></p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/big/frequency.png" alt=""></p><p>下面的操作都可以读取音频文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, samples)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, datatype)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, samples, datatype)</span></span></code></pre></div><p>samples 指定开始帧和结束帧，datatype 指定返回的数据类型。可以为所有变量设置值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; samples = [1, fs)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;&gt; [y, fs] = audioread (filename, samples)</span></span></code></pre></div><p>数据类型：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y,Fs] = audioread(filename,&#39;native&#39;)</span></span></code></pre></div><p>如果值是“native”，那么它的数据类型就依数据在音频文件中的存储情况而定。</p><h3 id="步骤4-音频文件的写操作" tabindex="-1">步骤4：音频文件的写操作 <a class="header-anchor" href="#步骤4-音频文件的写操作" aria-label="Permalink to “步骤4：音频文件的写操作”">​</a></h3><p>新建一个 ogg 文件：</p><p>我们会从一个余弦值创建一个 ogg 文件。采样率是每秒 44100 次，这个文件最少进行 10 秒的采样。余弦信号的频率是 440 Hz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; filename=&#39;cosine.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; fs=44100;</span></span>
<span class="line"><span>&gt;&gt; t=0:1/fs:10;</span></span>
<span class="line"><span>&gt;&gt; w=2*pi*440*t;</span></span>
<span class="line"><span>&gt;&gt; signal=cos(w);</span></span>
<span class="line"><span>&gt;&gt; audiowrite(filename, signal, fs);</span></span></code></pre></div><p>这就在工作路径中创建了一个 &#39;cosine.ogg&#39; 文件，这个文件中包含余弦信号。</p><p><img src="https://www.howtoforge.com/images/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/cosinefile.png" alt=""></p><p>播放这个 &#39;cosine.ogg&#39; 文件就会产生一个 440Hz 的 音调，这个音调正好是乐理中的 &#39;A&#39; 调。如果需要查看保存在文件中的值就必须使用 &#39;audioread&#39; 函数读取文件。在后续的教程中，我们会看到怎样在两个信道中读取一个音频文件。</p><h3 id="步骤5-播放音频文件" tabindex="-1">步骤5：播放音频文件 <a class="header-anchor" href="#步骤5-播放音频文件" aria-label="Permalink to “步骤5：播放音频文件”">​</a></h3><p>Octave 有一个默认的音频播放器，可以用这个音频播放器进行测试。使用下面的函数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y,fs]=audioread(&#39;yourfile.ogg&#39;);</span></span>
<span class="line"><span>&gt;&gt; player=audioplayer(y, fs, 8)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  scalar structure containing the fields:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    BitsPerSample =  8</span></span>
<span class="line"><span>    CurrentSample = 0</span></span>
<span class="line"><span>    DeviceID = -1</span></span>
<span class="line"><span>    NumberOfChannels =  1</span></span>
<span class="line"><span>    Running = off</span></span>
<span class="line"><span>    SampleRate =  44100</span></span>
<span class="line"><span>    TotalSamples =  236473</span></span>
<span class="line"><span>    Tag =</span></span>
<span class="line"><span>    Type = audioplayer</span></span>
<span class="line"><span>    UserData = [](0x0)</span></span>
<span class="line"><span>&gt;&gt; play(player);</span></span></code></pre></div><p>在这个教程的续篇，我们会进入音频处理的高级特性部分，可能会接触到一些科学和商业应用中的实例。</p><hr>`,40)),n("p",null,[a[1]||(a[1]=s("via: ",-1)),i(e,{href:"https://www.howtoforge.com/tutorial/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/"},{default:t(()=>[...a[0]||(a[0]=[s("https://www.howtoforge.com/tutorial/how-to-read-and-write-audio-files-with-octave-4-in-ubuntu/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=s("作者：",-1)),i(e,{href:"https://twitter.com/intent/follow?original_referer=https%3A%2F%2Fwww.howtoforge.com%2Ftutorial%2Fhow-to-read-and-write-audio-files-with-octave-4-in-ubuntu%2F&ref_src=twsrc%5Etfw&region=follow_link&screen_name=howtoforgecom&tw_p=followbutton"},{default:t(()=>[...a[2]||(a[2]=[s("David Duarte",-1)])]),_:1}),a[6]||(a[6]=s(" 译者：",-1)),i(e,{href:"https://github.com/vim-kakali"},{default:t(()=>[...a[3]||(a[3]=[s("vim-kakali",-1)])]),_:1}),a[7]||(a[7]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...a[9]||(a[9]=[s("Linux中国",-1)])]),_:1}),a[12]||(a[12]=s(" 荣誉推出",-1))])])}const y=p(g,[["render",h]]);export{v as __pageData,y as default};
